    "rawTitle": "Orb 01 — Bioluminescent Cyan Plasma Containment Sphere",
    "displayTitle": "Orb 01 — Bioluminescent Cyan Plasma Containment Sphere",
    "folderPath": "designs/orbs/orb 1/",
    "htmlPath": "designs/orbs/orb 1/index.html",
    "videoPath": "designs/orbs/orb 1/20261111-1401-20.7457571.mp4",
    "engine": "WEBGL 3D",
