    "id": "backgrounds__background-156",
    "section": "backgrounds",
    "name": "background 156",
    "rawTitle": "Background 156 — Radial Radar Sonar Sweep",
    "displayTitle": "Background 156 — Radial Radar Sonar Sweep",
    "folderPath": "designs/backgrounds/background 156/",
