    "id": "backgrounds__background-157",
    "section": "backgrounds",
    "name": "background 157",
    "rawTitle": "Background 157 — Blueprint Drafting Crosshair Grid",
    "displayTitle": "Background 157 — Blueprint Drafting Crosshair Grid",
    "folderPath": "designs/backgrounds/background 157/",
    "htmlPath": "designs/backgrounds/background 157/index.html",
    "videoPath": "",
    "engine": "CANVAS 2D",
    "hasImages": false,
    "hasBlueDefault": false,
    "defaultBgColor": "#0b1930",
    "htmlSource": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Background 157 — Blueprint Drafting Crosshair Grid</title>\n<style>\n  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }\n  html, body { width: 100%; height: 100%; overflow: hidden; background: #0b1930; user-select: none; -webkit-font-smoothing: antialiased; }\n  canvas { display: block; width: 100vw; height: 100vh; cursor: crosshair; }\n</style>\n</head>\n<body>\n<canvas id=\"stageCanvas\"></canvas>\n<script>\n(() => {\n  const canvas = document.getElementById('stageCanvas');\n  const ctx = canvas.getContext('2d'); if (!ctx) return;\n  let w = 0, h = 0, dpr = 1, ptrX = 0, ptrY = 0, tPtrX = 0, tPtrY = 0, grid = 48;\n  const pins = [];\n  function resize() {\n    dpr = Math.min(window.devicePixelRatio || 1, 2);\n    w = window.innerWidth; h = window.innerHeight;\n    canvas.width = Math.round(w * dpr); canvas.height = Math.round(h * dpr);\n    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);\n    tPtrX = ptrX = w * 0.5; tPtrY = ptrY = h * 0.5;\n  }\n  window.addEventListener('resize', resize); resize();\n  window.addEventListener('pointermove', (e) => { tPtrX = e.clientX; tPtrY = e.clientY; });\n  window.addEventListener('pointerdown', (e) => {\n    pins.push({ x: Math.round(e.clientX / grid) * grid, y: Math.round(e.clientY / grid) * grid, a: 1 });\n    if (pins.length > 8) pins.shift();\n  });\n  window.addEventListener('wheel', (e) => { grid = Math.max(28, Math.min(84, grid + (e.deltaY > 0 ? 4 : -4))); }, { passive: true });\n  function animate(now) {\n    const t = now * 0.001;\n    ptrX += (tPtrX - ptrX) * 0.16; ptrY += (tPtrY - ptrY) * 0.16;\n    ctx.fillStyle = '#0b1930'; ctx.fillRect(0, 0, w, h);\n    ctx.strokeStyle = 'rgba(147, 197, 253, 0.11)'; ctx.lineWidth = 1;\n    for (let x = 0; x < w; x += grid) { ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, h); ctx.stroke(); }\n    for (let y = 0; y < h; y += grid) { ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(w, y); ctx.stroke(); }\n    const sx = Math.round(ptrX / grid) * grid, sy = Math.round(ptrY / grid) * grid;\n    ctx.setLineDash([5, 5]); ctx.strokeStyle = 'rgba(96, 165, 250, 0.55)';\n    ctx.beginPath(); ctx.moveTo(sx, 0); ctx.lineTo(sx, h); ctx.moveTo(0, sy); ctx.lineTo(w, sy); ctx.stroke();\n    ctx.setLineDash([]);\n    ctx.strokeStyle = '#60a5fa'; ctx.lineWidth = 1.5;\n    ctx.beginPath(); ctx.arc(sx, sy, 14 + Math.sin(t * 3) * 3, 0, Math.PI * 2); ctx.stroke();\n    ctx.fillStyle = '#bfdbfe'; ctx.font = '11px monospace';\n    ctx.fillText(`X:${sx} Y:${sy}`, sx + 18, sy - 10);\n    for (let i = 0; i < pins.length; i++) {\n      const p = pins[i];\n      ctx.strokeStyle = 'rgba(191, 219, 254, 0.65)';\n      ctx.beginPath(); ctx.arc(p.x, p.y, 6, 0, Math.PI * 2); ctx.stroke();\n      if (i > 0) {\n        ctx.strokeStyle = 'rgba(96, 165, 250, 0.35)';\n        ctx.beginPath(); ctx.moveTo(pins[i - 1].x, pins[i - 1].y); ctx.lineTo(p.x, p.y); ctx.stroke();\n      }\n    }\n    requestAnimationFrame(animate);\n  }\n  requestAnimationFrame(animate);\n})();\n</script>\n</body>\n</html>\n",
