    "hasBlueDefault": false,
    "defaultBgColor": "#020806",
    "htmlSource": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Background 159 — Kinetic Falling Matrix Glyphs</title>\n<style>\n  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }\n  html, body { width: 100%; height: 100%; overflow: hidden; background: #020806; user-select: none; -webkit-font-smoothing: antialiased; }\n  canvas { display: block; width: 100vw; height: 100vh; cursor: pointer; }\n</style>\n</head>\n<body>\n<canvas id=\"stageCanvas\"></canvas>\n<script>\n(() => {\n  const canvas = document.getElementById('stageCanvas');\n  const ctx = canvas.getContext('2d'); if (!ctx) return;\n  const GLYPHS = '0123456789ABCDEF/<>[]{}*+-';\n  let w = 0, h = 0, dpr = 1, cols = 0, drops = [], ptrX = -999, ptrY = -999;\n  const fs = 16;\n  function resize() {\n    dpr = Math.min(window.devicePixelRatio || 1, 2);\n    w = window.innerWidth; h = window.innerHeight;\n    canvas.width = Math.round(w * dpr); canvas.height = Math.round(h * dpr);\n    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);\n    cols = Math.ceil(w / fs);\n    drops = Array.from({ length: cols }, () => ({ y: Math.random() * h, sp: 1.5 + Math.random() * 3.2 }));\n    ctx.fillStyle = '#020806'; ctx.fillRect(0, 0, w, h);\n  }\n  window.addEventListener('resize', resize); resize();\n  window.addEventListener('pointermove', (e) => { ptrX = e.clientX; ptrY = e.clientY; });\n  window.addEventListener('pointerleave', () => { ptrX = -999; ptrY = -999; });\n  window.addEventListener('pointerdown', () => { for (let i = 0; i < drops.length; i++) drops[i].sp = 4.5 + Math.random() * 3; });\n  function animate() {\n    ctx.fillStyle = 'rgba(2, 8, 6, 0.12)'; ctx.fillRect(0, 0, w, h);\n    ctx.font = `600 ${fs - 2}px monospace`;\n    for (let i = 0; i < cols; i++) {\n      const d = drops[i];\n      const x = i * fs;\n      const dist = Math.hypot(x - ptrX, d.y - ptrY);\n      const near = dist < 130;\n      ctx.fillStyle = near ? '#a7f3d0' : '#10b981';\n      const ch = GLYPHS[Math.floor(Math.random() * GLYPHS.length)];\n      ctx.fillText(ch, x, d.y);\n      d.y += d.sp * (near ? 1.8 : 1.0);\n      d.sp += (2.4 - d.sp) * 0.01;\n      if (d.y > h + fs && Math.random() > 0.96) d.y = -fs;\n    }\n    requestAnimationFrame(animate);\n  }\n  requestAnimationFrame(animate);\n})();\n</script>\n</body>\n</html>\n",
