    "id": "backgrounds__background-164",
    "section": "backgrounds",
    "name": "background 164",
    "rawTitle": "Background 164 — Concentric Breathing Polygons",
    "displayTitle": "Background 164 — Concentric Breathing Polygons",
    "folderPath": "designs/backgrounds/background 164/",
