    "engine": "CANVAS 2D",
    "hasImages": false,
    "hasBlueDefault": false,
    "defaultBgColor": "#06050c",
    "htmlSource": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Background 164 — Concentric Breathing Polygons</title>\n<style>\n  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }\n  html, body { width: 100%; height: 100%; overflow: hidden; background: #06050c; user-select: none; -webkit-font-smoothing: antialiased; }\n  canvas { display: block; width: 100vw; height: 100vh; cursor: pointer; }\n</style>\n</head>\n<body>\n<canvas id=\"stageCanvas\"></canvas>\n<script>\n(() => {\n  const canvas = document.getElementById('stageCanvas');\n  const ctx = canvas.getContext('2d'); if (!ctx) return;\n  let w = 0, h = 0, dpr = 1, ptrX = 0.5, ptrY = 0.5, tX = 0.5, tY = 0.5, sides = 6;\n  function resize() {\n    dpr = Math.min(window.devicePixelRatio || 1, 2);\n    w = window.innerWidth; h = window.innerHeight;\n    canvas.width = Math.round(w * dpr); canvas.height = Math.round(h * dpr);\n    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);\n  }\n  window.addEventListener('resize', resize); resize();\n  window.addEventListener('pointermove', (e) => { tX = e.clientX / Math.max(w, 1); tY = e.clientY / Math.max(h, 1); });\n  window.addEventListener('pointerdown', () => { sides = sides >= 9 ? 3 : sides + 1; });\n  function animate(now) {\n    const t = now * 0.001;\n    ptrX += (tX - ptrX) * 0.07; ptrY += (tY - ptrY) * 0.07;\n    ctx.fillStyle = '#06050c'; ctx.fillRect(0, 0, w, h);\n    const maxR = Math.hypot(w, h) * 0.58;\n    const count = 24;\n    for (let i = 0; i < count; i++) {\n      const u = ((i / count) + t * 0.08) % 1;\n      const r = Math.pow(u, 1.5) * maxR;\n      const cx = w * 0.5 + (ptrX - 0.5) * 160 * (1 - u);\n      const cy = h * 0.5 + (ptrY - 0.5) * 160 * (1 - u);\n      const rot = t * 0.35 + u * 1.4;\n      ctx.strokeStyle = `hsla(${Math.round(210 + u * 110)}, 90%, 66%, ${(Math.sin(u * Math.PI) * 0.72).toFixed(3)})`;\n      ctx.lineWidth = 1.2 + u * 1.6;\n      ctx.beginPath();\n      for (let s = 0; s <= sides; s++) {\n        const a = rot + (s / sides) * Math.PI * 2;\n        const px = cx + Math.cos(a) * r, py = cy + Math.sin(a) * r;\n        if (s === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);\n      }\n      ctx.stroke();\n    }\n    requestAnimationFrame(animate);\n  }\n  requestAnimationFrame(animate);\n})();\n</script>\n</body>\n</html>\n",
