    "videoPath": "",
    "engine": "CANVAS 2D",
    "hasImages": false,
    "hasBlueDefault": false,
    "defaultBgColor": "#05060b",
    "htmlSource": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Background 169 — Stage Volumetric Spotlight Beams</title>\n<style>\n  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }\n  html, body { width: 100%; height: 100%; overflow: hidden; background: #05060b; user-select: none; -webkit-font-smoothing: antialiased; }\n  canvas { display: block; width: 100vw; height: 100vh; cursor: pointer; }\n</style>\n</head>\n<body>\n<canvas id=\"stageCanvas\"></canvas>\n<script>\n(() => {\n  const canvas = document.getElementById('stageCanvas');\n  const ctx = canvas.getContext('2d'); if (!ctx) return;\n  let w = 0, h = 0, dpr = 1, ptrX = 0.5, ptrY = 0.65, tX = 0.5, tY = 0.65, flash = 0;\n  function resize() {\n    dpr = Math.min(window.devicePixelRatio || 1, 2);\n    w = window.innerWidth; h = window.innerHeight;\n    canvas.width = Math.round(w * dpr); canvas.height = Math.round(h * dpr);\n    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);\n  }\n  window.addEventListener('resize', resize); resize();\n  window.addEventListener('pointermove', (e) => { tX = e.clientX / Math.max(w, 1); tY = e.clientY / Math.max(h, 1); });\n  window.addEventListener('pointerdown', () => { flash = 1.0; });\n  const cols = ['56,189,248', '168,85,247', '244,114,182', '34,211,238', '129,140,248'];\n  function animate(now) {\n    const t = now * 0.001; ptrX += (tX - ptrX) * 0.07; ptrY += (tY - ptrY) * 0.07; flash *= 0.92;\n    ctx.globalCompositeOperation = 'source-over';\n    ctx.fillStyle = '#05060b'; ctx.fillRect(0, 0, w, h);\n    ctx.globalCompositeOperation = 'lighter';\n    for (let i = 0; i < 5; i++) {\n      const sx = w * (0.1 + i * 0.2);\n      const tx = ptrX * w + Math.sin(t * (0.7 + i * 0.15) + i * 1.4) * 160;\n      const ty = h + 80;\n      const spread = 85 + flash * 60;\n      const g = ctx.createLinearGradient(sx, 0, tx, ty);\n      g.addColorStop(0, `rgba(${cols[i]}, ${(0.32 + flash * 0.25).toFixed(3)})`);\n      g.addColorStop(1, `rgba(${cols[i]}, 0)`);\n      ctx.fillStyle = g;\n      ctx.beginPath(); ctx.moveTo(sx - 8, -10); ctx.lineTo(sx + 8, -10); ctx.lineTo(tx + spread, ty); ctx.lineTo(tx - spread, ty); ctx.closePath(); ctx.fill();\n    }\n    requestAnimationFrame(animate);\n  }\n  requestAnimationFrame(animate);\n})();\n</script>\n</body>\n</html>\n",
