    "htmlSource": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Background 202 — Harmonic Lissajous Oscilloscope</title>\n<style>\n  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }\n  html, body { width: 100%; height: 100%; overflow: hidden; background: #040a08; user-select: none; -webkit-font-smoothing: antialiased; }\n  canvas { display: block; width: 100vw; height: 100vh; cursor: pointer; }\n</style>\n</head>\n<body>\n<canvas id=\"stageCanvas\"></canvas>\n<script>\n(() => {\n  const canvas = document.getElementById('stageCanvas');\n  const ctx = canvas.getContext('2d'); if (!ctx) return;\n  let w = 0, h = 0, dpr = 1, ptrX = 0.5, ptrY = 0.5, tX = 0.5, tY = 0.5;\n  function resize() {\n    dpr = Math.min(window.devicePixelRatio || 1, 2);\n    w = window.innerWidth; h = window.innerHeight;\n    canvas.width = Math.round(w * dpr); canvas.height = Math.round(h * dpr);\n    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);\n  }\n  window.addEventListener('resize', resize); resize();\n  window.addEventListener('pointermove', (e) => { tX = e.clientX / Math.max(w, 1); tY = e.clientY / Math.max(h, 1); });\n  function animate(now) {\n    const t = now * 0.001; ptrX += (tX - ptrX) * 0.06; ptrY += (tY - ptrY) * 0.06;\n    ctx.fillStyle = 'rgba(4, 10, 8, 0.22)'; ctx.fillRect(0, 0, w, h);\n    const fx = 2 + Math.round(ptrX * 4), fy = 3 + Math.round(ptrY * 4);\n    const rx = w * 0.36, ry = h * 0.36;\n    for (let k = 0; k < 3; k++) {\n      ctx.strokeStyle = k === 0 ? 'rgba(52, 211, 153, 0.85)' : k === 1 ? 'rgba(34, 211, 238, 0.45)' : 'rgba(163, 230, 53, 0.25)';\n      ctx.lineWidth = k === 0 ? 1.8 : 1.1;\n      ctx.beginPath();\n      for (let i = 0; i <= 420; i++) {\n        const a = (i / 420) * Math.PI * 2;\n        const x = w * 0.5 + Math.sin(a * fx + t * 0.9 + k * 0.35) * rx;\n        const y = h * 0.5 + Math.sin(a * fy + k * 0.45) * ry;\n        if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);\n      }\n      ctx.stroke();\n    }\n    requestAnimationFrame(animate);\n  }\n  requestAnimationFrame(animate);\n})();\n</script>\n</body>\n</html>\n",
