    "videoPath": "",
    "engine": "CANVAS 2D",
    "hasImages": false,
    "hasBlueDefault": false,
    "defaultBgColor": "#05070e",
    "htmlSource": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Background 207 — Glowing Cellular Automata Life</title>\n<style>\n  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }\n  html, body { width: 100%; height: 100%; overflow: hidden; background: #05070e; user-select: none; -webkit-font-smoothing: antialiased; }\n  canvas { display: block; width: 100vw; height: 100vh; cursor: pointer; }\n</style>\n</head>\n<body>\n<canvas id=\"stageCanvas\"></canvas>\n<script>\n(() => {\n  const canvas = document.getElementById('stageCanvas');\n  const ctx = canvas.getContext('2d'); if (!ctx) return;\n  let w = 0, h = 0, dpr = 1, cols = 0, rows = 0, cell = 14, grid = [], heat = [], frame = 0;\n  function build() {\n    dpr = Math.min(window.devicePixelRatio || 1, 2);\n    w = window.innerWidth; h = window.innerHeight;\n    canvas.width = Math.round(w * dpr); canvas.height = Math.round(h * dpr);\n    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);\n    cols = Math.ceil(w / cell); rows = Math.ceil(h / cell);\n    grid = Array.from({ length: cols * rows }, () => (Math.random() > 0.78 ? 1 : 0));\n    heat = new Float32Array(cols * rows);\n  }\n  window.addEventListener('resize', build); build();\n  function paint(x, y) {\n    const cx = Math.floor(x / cell), cy = Math.floor(y / cell);\n    for (let dy = -2; dy <= 2; dy++) for (let dx = -2; dx <= 2; dx++) {\n      const nx = (cx + dx + cols) % cols, ny = (cy + dy + rows) % rows;\n      if (Math.random() > 0.35) grid[ny * cols + nx] = 1;\n    }\n  }\n  window.addEventListener('pointermove', (e) => { paint(e.clientX, e.clientY); });\n  window.addEventListener('pointerdown', (e) => { paint(e.clientX, e.clientY); });\n  function step() {\n    const next = new Array(cols * rows);\n    for (let y = 0; y < rows; y++) for (let x = 0; x < cols; x++) {\n      let n = 0;\n      for (let dy = -1; dy <= 1; dy++) for (let dx = -1; dx <= 1; dx++) {\n        if (!dx && !dy) continue;\n        n += grid[((y + dy + rows) % rows) * cols + ((x + dx + cols) % cols)];\n      }\n      const idx = y * cols + x;\n      next[idx] = grid[idx] ? (n === 2 || n === 3 ? 1 : 0) : (n === 3 ? 1 : 0);\n    }\n    grid = next;\n  }\n  function animate() {\n    if (++frame % 5 === 0) step();\n    ctx.fillStyle = '#05070e'; ctx.fillRect(0, 0, w, h);\n    for (let y = 0; y < rows; y++) for (let x = 0; x < cols; x++) {\n      const idx = y * cols + x;\n      heat[idx] = grid[idx] ? 1 : heat[idx] * 0.9;\n      if (heat[idx] < 0.04) continue;\n      ctx.fillStyle = `rgba(56, 189, 248, ${(heat[idx] * 0.85).toFixed(3)})`;\n      ctx.fillRect(x * cell + 1, y * cell + 1, cell - 2, cell - 2);\n    }\n    requestAnimationFrame(animate);\n  }\n  requestAnimationFrame(animate);\n})();\n</script>\n</body>\n</html>\n",
