    "engine": "CANVAS 2D",
    "hasImages": false,
    "hasBlueDefault": false,
    "defaultBgColor": "#09090b",
    "htmlSource": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Background 216 — Harmonic Chladni Acoustic Sand Plate</title>\n<style>\n  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }\n  html, body { width: 100%; height: 100%; overflow: hidden; background: #09090b; user-select: none; -webkit-font-smoothing: antialiased; }\n  canvas { display: block; width: 100vw; height: 100vh; cursor: pointer; }\n</style>\n</head>\n<body>\n<canvas id=\"stageCanvas\"></canvas>\n<script>\n(() => {\n  const canvas = document.getElementById('stageCanvas');\n  const ctx = canvas.getContext('2d'); if (!ctx) return;\n  let w = 0, h = 0, dpr = 1, n = 3, m = 5;\n  const grains = [];\n  function resize() {\n    dpr = Math.min(window.devicePixelRatio || 1, 2);\n    w = window.innerWidth; h = window.innerHeight;\n    canvas.width = Math.round(w * dpr); canvas.height = Math.round(h * dpr);\n    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);\n    if (!grains.length) for (let i = 0; i < 2400; i++) grains.push({ x: Math.random(), y: Math.random() });\n  }\n  window.addEventListener('resize', resize); resize();\n  window.addEventListener('pointermove', (e) => { n = 1 + Math.floor((e.clientX / Math.max(w, 1)) * 6); m = 2 + Math.floor((e.clientY / Math.max(h, 1)) * 6); });\n  window.addEventListener('pointerdown', () => { for (let i = 0; i < grains.length; i++) { grains[i].x = Math.random(); grains[i].y = Math.random(); } });\n  function animate() {\n    ctx.fillStyle = 'rgba(9, 9, 11, 0.35)'; ctx.fillRect(0, 0, w, h);\n    ctx.fillStyle = '#fde68a';\n    for (let i = 0; i < grains.length; i++) {\n      const g = grains[i];\n      const v = Math.cos(n * Math.PI * g.x) * Math.cos(m * Math.PI * g.y) - Math.cos(m * Math.PI * g.x) * Math.cos(n * Math.PI * g.y);\n      const jitter = Math.abs(v) * 0.025;\n      g.x = Math.max(0.01, Math.min(0.99, g.x + (Math.random() - 0.5) * jitter));\n      g.y = Math.max(0.01, Math.min(0.99, g.y + (Math.random() - 0.5) * jitter));\n      ctx.fillRect(g.x * w, g.y * h, 1.8, 1.8);\n    }\n    requestAnimationFrame(animate);\n  }\n  requestAnimationFrame(animate);\n})();\n</script>\n</body>\n</html>\n",
