    "htmlSource": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Background 223 — Misty Alpine Horizon Parallax</title>\n<style>\n  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }\n  html, body { width: 100%; height: 100%; overflow: hidden; background: #0f172a; user-select: none; -webkit-font-smoothing: antialiased; }\n  canvas { display: block; width: 100vw; height: 100vh; cursor: pointer; }\n</style>\n</head>\n<body>\n<canvas id=\"stageCanvas\"></canvas>\n<script>\n(() => {\n  const canvas = document.getElementById('stageCanvas');\n  const ctx = canvas.getContext('2d'); if (!ctx) return;\n  let w = 0, h = 0, dpr = 1, px = 0, tpx = 0;\n  function resize() {\n    dpr = Math.min(window.devicePixelRatio || 1, 2);\n    w = window.innerWidth; h = window.innerHeight;\n    canvas.width = Math.round(w * dpr); canvas.height = Math.round(h * dpr);\n    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);\n  }\n  window.addEventListener('resize', resize); resize();\n  window.addEventListener('pointermove', (e) => { tpx = (e.clientX / Math.max(w, 1) - 0.5) * 180; });\n  const cols = ['#334155', '#273449', '#1e293b', '#172033', '#0f172a', '#090e1a'];\n  function animate(now) {\n    const t = now * 0.0002; px += (tpx - px) * 0.05;\n    const sky = ctx.createLinearGradient(0, 0, 0, h);\n    sky.addColorStop(0, '#1e293b'); sky.addColorStop(0.55, '#475569'); sky.addColorStop(1, '#090e1a');\n    ctx.fillStyle = sky; ctx.fillRect(0, 0, w, h);\n    for (let l = 0; l < cols.length; l++) {\n      const baseY = h * (0.42 + l * 0.095), amp = 45 + l * 10, shift = t * (40 + l * 35) + px * (0.2 + l * 0.22);\n      ctx.fillStyle = cols[l];\n      ctx.beginPath(); ctx.moveTo(0, h);\n      for (let x = 0; x <= w; x += 12) {\n        const nx = (x + shift) * (0.0045 + l * 0.0012);\n        const y = baseY - Math.sin(nx) * amp - Math.cos(nx * 2.3 + l) * (amp * 0.45);\n        ctx.lineTo(x, y);\n      }\n      ctx.lineTo(w, h); ctx.closePath(); ctx.fill();\n    }\n    requestAnimationFrame(animate);\n  }\n  requestAnimationFrame(animate);\n})();\n</script>\n</body>\n</html>\n",
